import SwiftUI

struct PackingCard:View {@EnvironmentObject var s:NativeStore;var body:some View{VStack(alignment:.leading,spacing:8){Text("今日需带 \(s.packing["bottles"].int) 瓶饮料").bold();ForEach(s.packing["drinks"].list){c in Text(c["name"].text+" · "+s.label(s.customer(c.id)["buildingId"].text)+" · \(c["bottles"].int) 瓶").font(.caption)};Text("需带零钱 / 现金").bold();if s.packing["cash"].list.isEmpty{Text("无").font(.caption).foregroundStyle(.secondary)};ForEach(s.packing["cash"].list){c in Text(c["name"].text+" · "+s.label(s.customer(c.id)["buildingId"].text)+" · "+c["note"].text).font(.caption)}}.frame(maxWidth:.infinity,alignment:.leading).padding(14).background(Theme.background,in:RoundedRectangle(cornerRadius:16))}}
struct RouteView:View {
    @EnvironmentObject var s:NativeStore
    var body:some View{ScrollView{VStack(spacing:16){Card{PackingCard();let plan=s.fresh && s.live.exists ? s.live:s.day["plan"];HStack{metric("\(Int(ceil(plan["totalSeconds"].double/60)))","分钟");Spacer();metric(String(format:"%.1f",plan["distance"].double/1000),"公里");Spacer();metric(s.eta(obj(["arrivalSeconds":plan["totalSeconds"]])),"预计完成")}};Card{HStack{Text("配送路线").font(.headline);Spacer();NavigationLink("查看地图"){MapScreen()}};ForEach(Array(s.displayStops.enumerated()),id:\.offset){i,stop in StopCard(number:i+1,stop:stop)}};if s.day["startedAt"].exists{Card{Text("本趟步行记录").font(.headline);Text(String(format:"%.2f 公里",s.distance["metres"].double/1000)).font(.title2.bold());Text("保持前台更新位置与里程；全部送完后继续记录回家路程。").font(.caption).foregroundStyle(.secondary);if s.day["finishedAt"].exists{Text("本趟已结束")}else{MainButton(title:"完成本次配送 · 我到家了"){s.perform{try await s.finish()}}.disabled(!s.pending.isEmpty || s.day["needsReplan"].flag)}}};let completed=s.day["plan"]["stops"].list.flatMap{$0["customers"].list.filter{$0["delivered"].flag}};if !completed.isEmpty{Card{DisclosureGroup("已送达 \(completed.count) 位 · 可撤销"){ForEach(completed){c in HStack{Text(c["name"].text);Spacer();Button("撤销"){s.perform{try await s.delivered([c.id],false)}}.disabled(s.day["finishedAt"].exists)}}}}}}.padding(16)}.background(Theme.background).navigationTitle("待送 \(s.pending.count) 栋楼").navigationBarTitleDisplayMode(.inline)}
    func metric(_ value:String,_ title:String)->some View{VStack(alignment:.leading){Text(value).font(.title2.bold());Text(title).font(.caption).foregroundStyle(.secondary)}}
}
struct StopCard:View {@EnvironmentObject var s:NativeStore;let number:Int;let stop:J
    var body:some View{HStack(alignment:.top,spacing:10){NumberBadge(number:number);VStack(alignment:.leading,spacing:10){HStack(alignment:.top){Text(stop["building"]["name"].text).font(.headline);Spacer();Text(s.eta(stop)).font(.headline).foregroundColor(.blue)};Text(stop["building"]["address"].text).font(.caption).foregroundStyle(.secondary);Text("步行 \(Int(ceil(stop["walkSeconds"].double/60))) 分钟 · \(stop["customers"].list.count) 位顾客 · 楼下停留 2 分钟").font(.caption).foregroundStyle(.secondary);ForEach(stop["customers"].list){c in VStack(alignment:.leading,spacing:8){HStack{Text(c["name"].text).bold();Text("\(c["quantity"].int) 盒").font(.caption).foregroundStyle(.secondary);Spacer()};PhoneLink(phone:c["phone"].text);if !c["note"].text.isEmpty{Text(c["note"].text).font(.caption)};HStack{Button{UIPasteboard.general.string=c["name"].text+"，餐食预计 "+s.eta(stop)+" 送到 "+stop["building"]["name"].text+" 楼下，请到楼下交接。"}label:{Label("复制通知",systemImage:"doc.on.doc")};Spacer();Button{ s.perform{try await s.delivered([c.id])} }label:{Label("已送达",systemImage:"checkmark")}.disabled(s.busy)}}.font(.subheadline).padding(12).background(Theme.background,in:RoundedRectangle(cornerRadius:13))};HStack{Button("复制地址"){UIPasteboard.general.string=stop["building"]["address"].text};Spacer();Button("整栋已送达"){s.perform{try await s.delivered(stop["customers"].list.map(\.id))}}.disabled(s.busy)}.font(.subheadline)}.padding(12).overlay(RoundedRectangle(cornerRadius:16).stroke(Color.gray.opacity(0.2)))}.padding(.vertical,6)}
}
struct PhoneLink:View {let phone:String;var body:some View{if let url=URL(string:"tel:"+phone.filter{"+0123456789".contains($0)}),!phone.isEmpty{Link(destination:url){Label(phone+" 拨打",systemImage:"phone").font(.subheadline)}}}}
struct MapScreen:View {@EnvironmentObject var s:NativeStore;var body:some View{VStack{NativeMap(stops:s.displayStops,geometry:s.fresh && s.live.exists ? s.live["geometry"]:s.day["plan"]["geometry"],position:s.fresh ? s.position:.null);Text(s.locationMessage).font(.caption).padding(8);Button(s.tracking ? "关闭实时定位":"开启实时定位"){if s.tracking{s.stopLocation()}else{s.startLocation()}}.padding()}.padding(12).background(Theme.background).navigationTitle("配送地图").navigationBarTitleDisplayMode(.inline)}}
struct DirectoryView:View {
    @EnvironmentObject var s:NativeStore;@State var segment=0;@State var search="";@State var edit:J?;@State var new=false
    var body:some View{ScrollView{VStack(spacing:16){Brand();Picker("分类",selection:$segment){Text("常客档案 \(s.customers.count)").tag(0);Text("楼栋与出发点").tag(1)}.pickerStyle(.segmented);Card{HStack{Image(systemName:"magnifyingglass");TextField("搜索姓名、电话、备注或公寓",text:$search);Button{edit=nil;new=true}label:{Image(systemName:"plus.circle.fill").font(.title2)}}};Card{let rows=(segment==0 ? s.customers:s.buildings).filter{search.isEmpty || ($0["name"].text+$0["phone"].text+$0["note"].text+$0["address"].text+s.label($0["buildingId"].text)).localizedCaseInsensitiveContains(search)};if rows.isEmpty{Text("暂无匹配记录").foregroundStyle(.secondary)};ForEach(rows){c in HStack(alignment:.top){Text(String(c["name"].text.prefix(1))).font(.headline).foregroundColor(.blue).frame(width:36,height:36).background(Theme.background,in:RoundedRectangle(cornerRadius:12));VStack(alignment:.leading,spacing:6){Text(c["name"].text).font(.headline);Text(segment==0 ? s.label(c["buildingId"].text):c["address"].text).font(.caption).foregroundStyle(.secondary);if segment==0{PhoneLink(phone:c["phone"].text);if !c["note"].text.isEmpty{Text(c["note"].text).font(.caption).foregroundStyle(.secondary)}}};Spacer();Button("编辑"){edit=c;new=true}};Divider()}}}.padding(16)}.background(Theme.background).navigationTitle("顾客与楼栋").navigationBarTitleDisplayMode(.inline).sheet(isPresented:$new){if segment==0{CustomerEditor(initial:edit).environmentObject(s)}else{BuildingEditor(initial:edit).environmentObject(s)}}}
}
struct CustomerEditor:View {@EnvironmentObject var s:NativeStore;@Environment(\.dismiss) var dismiss;let initial:J?;@State var name="";@State var phone="";@State var note="";@State var building="";var body:some View{NavigationStack{Form{TextField("姓名",text:$name);TextField("电话 / 联系方式",text:$phone).keyboardType(.phonePad);Picker("交接楼栋",selection:$building){Text("请选择").tag("");ForEach(s.buildings){b in Text(s.label(b.id)).tag(b.id)}};TextField("备注",text:$note,axis:.vertical)}.navigationTitle(initial==nil ? "新顾客":"编辑顾客").toolbar{ToolbarItem(placement:.cancellationAction){Button("取消"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("保存"){s.perform{try await s.save("customer",obj(["id":str(initial?.id ?? ""),"name":str(name),"phone":str(phone),"note":str(note),"buildingId":str(building)]));dismiss()}}.disabled(name.isEmpty || building.isEmpty || s.busy)}}.onAppear{name=initial?["name"].text ?? "";phone=initial?["phone"].text ?? "";note=initial?["note"].text ?? "";building=initial?["buildingId"].text ?? ""}}}}
struct BuildingEditor:View {@EnvironmentObject var s:NativeStore;@Environment(\.dismiss) var dismiss;let initial:J?;@State var name="";@State var address="";@State var search="";@State var results:[J]=[];@State var pin:J = .null;var body:some View{NavigationStack{ScrollView{VStack(spacing:16){TextField("公寓 / 楼栋名称",text:$name).textFieldStyle(.roundedBorder);TextField("完整地址",text:$address).textFieldStyle(.roundedBorder);HStack{TextField("搜索离线公寓目录",text:$search).textFieldStyle(.roundedBorder);Button("搜索"){s.perform{results=try await s.call("locations",obj(["text":str(search),"state":s.state])).list}}};ForEach(Array(results.enumerated()),id:\.offset){_,b in Button{pin=b;name=b["name"].text;address=b["address"].text;results=[]}label:{Text(b["name"].text).frame(maxWidth:.infinity,alignment:.leading).padding(8)}};NativeMap(pin:pin,onPick:{lng,lat in pin=obj(["lng":num(lng),"lat":num(lat)])}).frame(height:350);Text("点击地图调整楼下交接点。已匹配位置可直接保存。").font(.caption).foregroundStyle(.secondary)}.padding()}.navigationTitle("楼栋与入口").toolbar{ToolbarItem(placement:.cancellationAction){Button("取消"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("保存"){s.perform{try await s.save("building",obj(["id":str(initial?.id ?? UUID().uuidString),"name":str(name),"address":str(address),"lat":pin["lat"],"lng":pin["lng"]]));dismiss()}}.disabled(name.isEmpty || address.isEmpty || !pin.exists || s.busy)}}.onAppear{name=initial?["name"].text ?? "";address=initial?["address"].text ?? "";pin=initial ?? .null}}}}
struct PasteSheet:View {
    @EnvironmentObject var s:NativeStore;@Environment(\.dismiss) var dismiss
    @State var text="";@State var rows:[J]=[];@State var selected:Int?;@State var search="";@State var results:[J]=[]
    func field(_ index:Int,_ key:String)->Binding<String>{Binding(get:{rows[index][key].text},set:{rows[index][key]=str($0)})}
    var body:some View{NavigationStack{ScrollView{VStack(spacing:16){Card{Text("粘贴微信顾客信息").font(.headline);TextEditor(text:$text).frame(height:150).overlay(RoundedRectangle(cornerRadius:8).stroke(Color.gray.opacity(0.2)));Text("自动过滤发送人标题；识别后可逐项修改。").font(.caption).foregroundStyle(.secondary);MainButton(title:"识别顾客",icon:"text.viewfinder"){s.perform{rows=try await s.call("parse",obj(["text":str(text),"state":s.state])).list}}};ForEach(rows.indices,id:\.self){i in Card{HStack{Text("\(i+1) · "+(rows[i]["customerId"].text.isEmpty ? "新顾客":"已匹配常客")).font(.headline);Spacer();Button{rows.remove(at:i)}label:{Image(systemName:"trash")}};TextField("姓名",text:field(i,"name")).textFieldStyle(.roundedBorder);TextField("电话 / 联系方式",text:field(i,"phone")).keyboardType(.phonePad).textFieldStyle(.roundedBorder);Stepper(value:Binding(get:{rows[i]["quantity"].int},set:{rows[i]["quantity"]=num(Double($0))}),in:0...99){Text("\(rows[i]["quantity"].int) 盒")};TextField("楼栋名称",text:field(i,"buildingName")).textFieldStyle(.roundedBorder);TextField("地址",text:field(i,"address")).textFieldStyle(.roundedBorder);Button(rows[i]["locationConfirmed"].flag ? "已定位 · 调整楼栋 / 入口":"请选择楼栋 / 入口"){selected=i;search=rows[i]["buildingName"].text;results=[]};TextField("本次备注",text:field(i,"note"),axis:.vertical).textFieldStyle(.roundedBorder);if !rows[i]["warnings"].list.isEmpty{Text(rows[i]["warnings"].list.map(\.text).joined(separator:"；")).font(.caption).foregroundStyle(.secondary)};DisclosureGroup("查看原文"){Text(rows[i]["raw"].text).font(.caption)}}};if !rows.isEmpty{MainButton(title:"保存并加入本趟配送",icon:"plus"){s.perform{let payload=rows.map{r in obj(["name":r["name"],"phone":r["phone"],"note":r["note"],"quantity":r["quantity"],"customerId":r["customerId"],"locationConfirmed":r["locationConfirmed"],"building":obj(["id":str(r["buildingId"].text.isEmpty ? UUID().uuidString:r["buildingId"].text),"name":r["buildingName"],"address":r["address"],"lat":r["lat"],"lng":r["lng"]])])};try await s.save("import",obj(["rows":.array(payload),"day":s.day,"addToDay":.bool(true)]));s.dirty=false;try await s.refresh();dismiss()}}.disabled(s.busy || rows.contains{$0["name"].text.isEmpty || !$0["locationConfirmed"].flag})}}.padding(16)}.background(Theme.background).navigationTitle("批量添加顾客").toolbar{Button("关闭"){dismiss()}}.sheet(isPresented:Binding(get:{selected != nil},set:{if !$0{selected=nil}})){NavigationStack{ScrollView{VStack{HStack{TextField("公寓名称",text:$search).textFieldStyle(.roundedBorder);Button("搜索"){s.perform{results=try await s.call("locations",obj(["text":str(search),"state":s.state])).list}}};ForEach(Array(results.enumerated()),id:\.offset){_,b in Button{if let i=selected{rows[i]["buildingId"]=b["id"];rows[i]["buildingName"]=b["name"];rows[i]["address"]=b["address"];rows[i]["lat"]=b["lat"];rows[i]["lng"]=b["lng"];rows[i]["locationConfirmed"] = .bool(true)};selected=nil}label:{Text(b["name"].text).padding(12).frame(maxWidth:.infinity,alignment:.leading)}};if let i=selected{NativeMap(pin:rows[i]["lat"].exists ? obj(["lat":rows[i]["lat"],"lng":rows[i]["lng"]]):.null,onPick:{lng,lat in rows[i]["lat"]=num(lat);rows[i]["lng"]=num(lng);rows[i]["buildingId"]=str("");rows[i]["locationConfirmed"] = .bool(true)}).frame(height:380)}}.padding()}.navigationTitle("选择交接点").toolbar{Button("完成"){selected=nil}}}}}}
}
struct HistoryView:View {@EnvironmentObject var s:NativeStore;@State var newest=true;@State var month="全部时间";var months:[String]{Array(Set(s.state["days"].list.map{String($0["date"].text.prefix(7))})).sorted(by:>)};var body:some View{ScrollView{VStack(spacing:16){Brand();Card{HStack{Picker("时间",selection:$month){Text("全部时间").tag("全部时间");ForEach(months,id:\.self){Text($0).tag($0)}};Spacer();Button(newest ? "新 → 旧":"旧 → 新"){newest.toggle()}}};ForEach(newest ? months:Array(months.reversed()),id:\.self){m in if month=="全部时间" || month==m {let days=s.state["days"].list.filter{$0["date"].text.hasPrefix(m)}.sorted{newest ? $0["date"].text>$1["date"].text:$0["date"].text<$1["date"].text};Card{HStack{Text(m).font(.headline);Spacer();Text("\(days.count) 天 · \(days.reduce(0){$0+totalBoxes($1)}) 盒").font(.caption).foregroundStyle(.secondary)};ForEach(days,id:\.self){d in HStack(alignment:.top){VStack(alignment:.leading){Text(d["date"].text).foregroundColor(.blue);Text(weekday(d["date"].text)).font(.caption).foregroundStyle(.secondary)};VStack(alignment:.leading){Text("共 \(totalBoxes(d)) 盒").bold();Text(s.state["menus"].list.first{$0["date"]==d["date"]}?["dishes"].list.map{$0["name"].text}.joined(separator:" + ") ?? "未记录菜品").font(.caption).foregroundStyle(.secondary)};Spacer();NavigationLink("查看"){HistoryDetail(day:d)}}.font(.subheadline);Divider()}}}}}.padding(16)}.background(Theme.background).navigationTitle("历史记录").navigationBarTitleDisplayMode(.inline)}}
struct HistoryDetail:View {@EnvironmentObject var s:NativeStore;let day:J;var body:some View{List{Section(day["date"].text+" · "+weekday(day["date"].text)){Text("共 \(totalBoxes(day)) 盒");Text(s.state["menus"].list.first{$0["date"]==day["date"]}?["dishes"].list.map{$0["name"].text}.joined(separator:" + ") ?? "未记录菜品")};ForEach(Array((day["previousTrips"].list+[day]).enumerated()),id:\.offset){i,trip in Section("第 \(i+1) 趟"){ForEach(trip["orders"].list,id:\.self){o in HStack{Text(s.customer(o["customerId"].text)["name"].text);Spacer();Text("\(o["quantity"].int) 盒")}}}}}.navigationTitle("当日详情")}}
struct StatisticsView:View {@EnvironmentObject var s:NativeStore;@State var weeks=1;@State var date=Date();@State var stats:J = .null;var body:some View{ScrollView{VStack(spacing:16){Brand();Card{HStack{Label("经营统计",systemImage:"chart.bar").font(.headline);Spacer();Picker("周期",selection:$weeks){Text("每周").tag(1);Text("每四周").tag(4)}.pickerStyle(.segmented).frame(width:170)};DatePicker("统计日期",selection:$date,displayedComponents:.date);Text(stats["start"].text+" — "+stats["end"].text).font(.caption).foregroundStyle(.secondary);HStack{stat("\(stats["boxes"].int)","订单盒数");Spacer();stat("\(stats["customers"].list.count)","订餐顾客");Spacer();stat("\(stats["orderDays"].int)","营业天数")}};RankingCard(title:"顾客订餐排行",rows:stats["customers"].list);RankingCard(title:"肉菜销量排行",rows:stats["meats"].list);if !stats["missing"].list.isEmpty{Card{Text("\(stats["missing"].list.count) 天未记录菜单，未计入菜品销量。").font(.caption).foregroundStyle(.secondary)}}}.padding(16)}.background(Theme.background).navigationTitle("经营统计").navigationBarTitleDisplayMode(.inline).task(id:"\(weeks)-\(londonDate(date))-\(s.state["revision"].int)"){guard s.ready else{return};if s.demo{stats=obj(["boxes":num(2),"customers":.array([obj(["id":str("c"),"name":str("演示顾客"),"boxes":num(2),"days":num(1)])]),"meats":.array([]),"orderDays":num(1)]);return};do{stats=try await s.call("stats",obj(["date":str(londonDate(date)),"weeks":num(Double(weeks)),"state":s.state]))}catch{s.handle(error)}}}
    func stat(_ value:String,_ title:String)->some View{VStack(alignment:.leading){Text(value).font(.title.bold());Text(title).font(.caption).foregroundStyle(.secondary)}}
}
struct RankingCard:View {let title:String;let rows:[J];@State var all=false;var body:some View{Card{HStack{Text(title).font(.headline);Spacer();Button(all ? "收起":"查看全部"){all.toggle()}};if rows.isEmpty{Text("暂无记录").foregroundStyle(.secondary)};ForEach(Array((all ? rows:Array(rows.prefix(5))).enumerated()),id:\.offset){i,row in HStack{Text("\(i+1)").font(.caption.bold()).frame(width:26,height:26).background(Theme.background,in:Circle());VStack(alignment:.leading){Text(row["name"].text).bold();Text("\(row["days"].int) 天"+(row["lastDate"].text.isEmpty ? "":" · 最近 "+row["lastDate"].text)).font(.caption).foregroundStyle(.secondary)};Spacer();Text("\(row["boxes"].int) 盒").foregroundColor(.blue)};Divider()}}}}
